import {
  Scene,
  OrthographicCamera,
  Vector2,
  ShaderMaterial,
  DoubleSide,
  Mesh,
  PlaneBufferGeometry,
  WebGLRenderer,
} from "three";
import fragmentShader from "./fragmentShader.glsl";
import vertexShader from "./vertexShader.glsl";
import { createRenderLoop } from "../three/render-loop.js";

const REVEAL_DURATION = 1500;

export function initializePreloader(canvas) {
  const scene = new Scene();
  const mouse = new Vector2();
  const material = new ShaderMaterial({
    precision: "lowp",
    side: DoubleSide,
    uniforms: {
      uAlpha: { value: 0.5 },
      uMouse: { value: mouse },
      uTime: { value: 0 },
      uRes: { value: new Vector2() },
      uRadius: { value: 0.01 },
      uBlur: { value: 4 },
    },
    vertexShader,
    fragmentShader,
    defines: { PR: Math.min(window.devicePixelRatio, 2).toFixed(2) },
  });

  scene.add(new Mesh(new PlaneBufferGeometry(2, 2), material));
  const camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
  const renderer = new WebGLRenderer({
    canvas,
    alpha: true,
    antialias: false,
    powerPreference: "high-performance",
  });
  canvas.style.backgroundColor = "unset";

  const resize = () => {
    const width = window.innerWidth;
    const height = window.innerHeight;
    material.uniforms.uRes.value.set(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(width, height, false);
  };
  const updateMouse = (event) => {
    mouse.set(
      event.clientX / window.innerWidth - 0.5,
      -(event.clientY / window.innerHeight - 0.5),
    );
  };
  const preventScroll = (event) => event.preventDefault();

  window.addEventListener("resize", resize);
  window.addEventListener("mousemove", updateMouse);
  canvas.addEventListener("wheel", preventScroll, { passive: false });
  resize();

  let revealStartedAt;
  let previousFrameTime;
  let resolveFinished;
  const finished = new Promise((resolve) => {
    resolveFinished = resolve;
  });
  const stop = createRenderLoop((time) => {
    const delta = previousFrameTime === undefined
      ? 0
      : time - previousFrameTime;
    previousFrameTime = time;
    material.uniforms.uTime.value = (
      material.uniforms.uTime.value + delta / 1000
    ) % 1000;

    if (revealStartedAt !== undefined) {
      const progress = Math.min((time - revealStartedAt) / REVEAL_DURATION, 1);
      material.uniforms.uRadius.value = 0.01 + progress * 3.99;
      material.uniforms.uBlur.value = 4 * (1 - progress);
      if (progress === 1) {
        // The loop callback can run only after initialization is complete.
        // eslint-disable-next-line no-use-before-define
        dispose();
        canvas.remove();
        resolveFinished();
      }
    }

    renderer.render(scene, camera);
  }, canvas);

  const finish = () => {
    if (revealStartedAt === undefined) {
      revealStartedAt = performance.now();
    }
    return finished;
  };

  const dispose = () => {
    stop();
    window.removeEventListener("resize", resize);
    window.removeEventListener("mousemove", updateMouse);
    canvas.removeEventListener("wheel", preventScroll);
    renderer.dispose();
    material.dispose();
  };

  return { finish, dispose };
}
